<script>
document.addEventListener('DOMContentLoaded',function(){const p=document.getElementById('programme_id'),s=document.getElementById('study_plan_id'),code=document.querySelector('[name="code"]'),suggestions=@json($codeSuggestions ?? []),form=s?.closest('form'),error=document.getElementById('plan-error');function filter(){const value=p.value;let count=0;[...s.options].forEach(o=>{if(!o.value)return;o.hidden=value!==''&&o.dataset.programme!==value;if(!o.hidden)count++;if(o.hidden&&o.selected)s.value='';});if(code&&!code.dataset.touched&&suggestions[value])code.value=suggestions[value];if(error)error.textContent=value&&count===0?'No Curriculum exists for this Programme. Create its plan first, then return to finish this draft.':'';}if(code){code.addEventListener('input',()=>code.dataset.touched='1');}p.addEventListener('change',filter);filter();});
</script>
